mapper.delete:

 /* deleteData - Lee  MS */

DELETE FROM AEA130 /* 복지시설사례종결 */
WHERE A.CASE_MNG_NO = #{CASE_MNG_NO}
  AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

mapper.select:
/* selectReqById - Lee MS */
SELECT A.ENTRNC_XTND_YMD AS ENTRNC_XTND_YMD, /* 입소연장일자 */ A.ENTRNC_XTND_CS_SE_CD AS ENTRNC_XTND_CS_SE_CD, /* 입소연장사유구분코드 */ A.ENTRNC_XTND_CS_ETC_CN AS ENTRNC_XTND_CS_ETC_CN, /* 입소연장사유기타내용 */
A.PIC_NO AS PIC_NO, /* 담당자번호 */ C##RG.DEC_B64(B.FLNM_ENCPT) AS PIC_NM, /* 성명암호화 */ A.INST_NO AS INST_NO, /* 기관번호 */ C.INST_NM AS INST_NM, /* 기관명 */
A.CASE_MNG_NO AS CASE_MNG_NO, /* 사례관리번호 */ A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO, /* 사례관리차수 */ A.ENTRNC_XTND_SN AS ENTRNC_XTND_SN /* 입소연장일련번호 */
FROM AEA131 A, SCA100 B, SAA000 C /* 입소연장정보, 통합기관*/ WHERE A.PIC_NO = B.ENFSN_NO AND A.INST_NO = C.INST_NO AND A.CASE_MNG_NO = #{CASE_MNG_NO} AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

mapper.delete:

 /* deleteData - Lee  MS */

DELETE FROM AEA131 A /* 입소연장정보 */
WHERE A.CASE_MNG_NO = #{CASE_MNG_NO}
  AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
  AND A.ENTRNC_XTND_SN = #{ENTRNC_XTND_SN}
